"use client";

import { useEffect, useState } from "react";
import { apiGet } from "@/lib/api-client";
import { useAppStore } from "@/store/app-store";
import { PublicSite } from "@/components/public/public-site";
import { AppShell } from "@/components/app/app-shell";
import { LoadingState } from "@/components/app/empty-state";

export default function Home() {
  const { user, setUser, intendedDestination, navigate, setIntendedDestination } = useAppStore();
  const [checking, setChecking] = useState(true);

  useEffect(() => {
    let active = true;
    (async () => {
      try {
        const data = await apiGet("/auth/me");
        if (active) {
          if (data.user) {
            setUser(data.user);
            // If already logged in and has intended destination, navigate there
            if (intendedDestination) {
              // Only allow request-create for CUSTOMER; others go to dashboard
              if (data.user.roleId === "CUSTOMER" && intendedDestination === "request-create") {
                navigate(intendedDestination);
              } else {
                navigate("dashboard");
              }
              setIntendedDestination(null);
            }
          }
          setChecking(false);
        }
      } catch {
        if (active) setChecking(false);
      }
    })();
    return () => { active = false; };
  }, [setUser]);

  if (checking) {
    return (
      <div className="flex min-h-screen flex-col items-center justify-center bg-background">
        <LoadingState className="py-0" />
      </div>
    );
  }

  if (!user) return <PublicSite />;

  // If user just logged in and has intended destination
  if (intendedDestination) {
    if (user.roleId === "CUSTOMER" && intendedDestination === "request-create") {
      navigate(intendedDestination);
    } else {
      navigate("dashboard");
    }
    setIntendedDestination(null);
  }

  return <AppShell />;
}
