// Client-side API helper cho EQUIDELI kết nối với Spring Boot
// Sử dụng biến môi trường hoặc mặc định trỏ về backend Spring Boot
const BASE = process.env.NEXT_PUBLIC_API_BASE_URL || "http://localhost:8080";

export class ApiError extends Error {
  status: number;
  details?: any;
  constructor(message: string, status: number, details?: any) {
    super(message);
    this.status = status;
    this.details = details;
  }
}

export async function api<T = any>(
  path: string,
  options?: RequestInit
): Promise<T> {
  const headers = new Headers(options?.headers);
  const isFormData = typeof FormData !== "undefined" && options?.body instanceof FormData;
  
  if (!isFormData && !headers.has("Content-Type")) {
    headers.set("Content-Type", "application/json");
  }

  // Tự động lấy JWT token từ localStorage và gắn vào Header
  if (typeof window !== "undefined") {
    const token = localStorage.getItem("token");
    if (token) {
      headers.set("Authorization", `Bearer ${token}`);
    }
  }

  const res = await fetch(`${BASE}${path}`, {
    ...options,
    headers,
  });

  const text = await res.text();
  let data: any = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = text;
  }

  if (!res.ok) {
    const message = data?.error || data?.message || `Lỗi ${res.status}`;
    // Nếu lỗi 401 (Unauthorized), có thể thêm logic tự động đăng xuất tại đây
    if (res.status === 401 && typeof window !== "undefined") {
      localStorage.removeItem("token");
      // window.location.href = '/login'; // Mở comment dòng này nếu muốn tự động đá về trang đăng nhập
    }
    throw new ApiError(message, res.status, data);
  }

  return data as T;
}

export const apiGet = <T = any>(path: string) => api<T>(path);
export const apiPost = <T = any>(path: string, body?: any) =>
  api<T>(path, { method: "POST", body: body ? JSON.stringify(body) : undefined });
export const apiPostFormData = <T = any>(path: string, body: FormData) =>
  api<T>(path, { method: "POST", body });
export const apiPut = <T = any>(path: string, body?: any) =>
  api<T>(path, { method: "PUT", body: body ? JSON.stringify(body) : undefined });
export const apiPatch = <T = any>(path: string, body?: any) => // Bổ sung apiPatch cho các endpoint PATCH trong Task.docx
  api<T>(path, { method: "PATCH", body: body ? JSON.stringify(body) : undefined });
export const apiDelete = <T = any>(path: string) =>
  api<T>(path, { method: "DELETE" });